class Solution {
public:
    int maxNumberOfFamilies(int n, vector<vector<int>>& reservedSeats) {
        unordered_map<int, int> rowMask;
        for (auto& rs : reservedSeats) {
            rowMask[rs[0]] |= (1 << rs[1]);
        }
        int ans = 2 * (n - (int)rowMask.size());
        for (auto& [row, mask] : rowMask) {
            bool left   = !(mask & 0x3C);   // seats 2,3,4,5
            bool middle = !(mask & 0xF0);  // seats 4,5,6,7
            bool right  = !(mask & 0x3C0);  // seats 6,7,8,9
            if (left && right) {
                ans += 2;
            } else if (left || middle || right) {
                ans += 1;
            }
        }
        return ans;
    }
};
